#![allow(unexpected_cfgs)]
//! # edgeforge-runtime-sys — Unsafe FFI Bindings to llama.cpp
//!
//! ## Purpose
//! The ONLY crate in the workspace allowed to use `unsafe`. Contains the raw
//! C ABI bindings to llama.cpp, generated by bindgen from `wrapper.h`.
//!
//! ## What This File Does
//! This file conditionally compiles in one of two modes:
//!
//! - **Real mode** (`llama-backend` feature + llama.cpp built): Includes the
//!   bindgen-generated bindings from `OUT_DIR/bindings.rs` and provides safe
//!   wrapper functions for model loading, tokenization, and generation.
//!
//! - **Stub mode** (default, no feature or no llama.cpp): All functions return
//!   `Err(NotImplemented)`. The `MockInferenceEngine` is used instead.
//!
//! ## Dependencies
//! - `cc`, `cmake`, `bindgen` (build-dependencies) — for building llama.cpp
//! - Links to `llama` static library (when in real mode)
//!
//! ## Architectural Invariants
//! - `cargo-deny` blocks `unsafe` outside this crate and `edgeforge-storage/platform/*`.
//! - Kani proof harnesses required for every `unsafe` block (ADR-025, ≥90% coverage).
//! - Panics must not unwind across the FFI boundary (would be UB).
//!
//! ## Safe Wrapper API
//! The safe wrappers provide:
//! - `load_model(path, params)` → `Result<LlamaModel, FfiError>`
//! - `tokenize(model, text)` → `Result<Vec<i32>, FfiError>`
//! - `decode(model, batch)` → `Result<(), FfiError>`
//! - `sample_token(model, logits)` → `Result<i32, FfiError>`
//! - `token_to_piece(model, token)` → `Result<String, FfiError>`
//! - `free_model(model)` — cleanup

// ── Stub mode ────────────────────────────────────────────────────────────
// When llama.cpp is not built, we compile stub types and functions that
// return NotImplemented errors. This lets the workspace compile without
// the C++ toolchain.

#[cfg(llama_stub)]
pub mod stub;

#[cfg(llama_stub)]
pub use stub::*;

// ── Real mode ────────────────────────────────────────────────────────────
// When llama.cpp IS built, we include the bindgen-generated bindings and
// provide safe wrappers around the unsafe FFI calls.

#[cfg(not(llama_stub))]
pub mod real;

#[cfg(not(llama_stub))]
pub use real::*;

// ── Common types (used in both modes) ────────────────────────────────────

/// Error type for FFI operations.
#[derive(Debug, Clone)]
pub enum FfiError {
    /// The FFI backend is not available (stub mode).
    NotImplemented(&'static str),
    /// An FFI call returned an error.
    Ffi(String),
    /// A null pointer was encountered.
    NullPointer,
    /// An invalid argument was passed.
    InvalidArgument(String),
}

impl std::fmt::Display for FfiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(msg) => write!(f, "FFI not implemented: {msg}"),
            Self::Ffi(msg) => write!(f, "FFI error: {msg}"),
            Self::NullPointer => write!(f, "FFI null pointer"),
            Self::InvalidArgument(msg) => write!(f, "FFI invalid argument: {msg}"),
        }
    }
}

impl std::error::Error for FfiError {}

impl From<FfiError> for edgeforge_core::EdgeForgeError {
    fn from(e: FfiError) -> Self {
        match e {
            FfiError::NotImplemented(msg) => Self::NotImplemented(msg),
            other => Self::Engine(other.to_string()),
        }
    }
}

/// Parameters for loading a model via the FFI.
#[derive(Debug, Clone)]
pub struct LlamaModelParams {
    /// Number of context tokens (context window size).
    pub n_ctx: u32,
    /// Number of GPU layers to offload (0 = CPU only).
    pub n_gpu_layers: u32,
    /// Whether to use memory mapping for the model file.
    pub use_mmap: bool,
    /// Whether to use memory locking (prevent swap).
    pub use_mlock: bool,
}

impl Default for LlamaModelParams {
    fn default() -> Self {
        Self {
            n_ctx: 4096,
            n_gpu_layers: 0,
            use_mmap: true,
            use_mlock: false,
        }
    }
}

/// Parameters for text generation via the FFI.
#[derive(Debug, Clone)]
pub struct LlamaGenerationParams {
    /// Number of tokens to generate.
    pub n_predict: i32,
    /// Sampling temperature (0.0 = greedy, 1.0 = creative).
    pub temp: f32,
    /// Top-p sampling threshold.
    pub top_p: f32,
    /// Random seed (-1 = random).
    pub seed: i64,
    /// Stop sequences (strings that halt generation).
    pub stop_sequences: Vec<String>,
}

impl Default for LlamaGenerationParams {
    fn default() -> Self {
        Self {
            n_predict: 512,
            temp: 0.7,
            top_p: 0.9,
            seed: -1,
            stop_sequences: Vec::new(),
        }
    }
}

/// Opaque handle to a loaded llama.cpp model.
/// In stub mode, this is a dummy type.
/// In real mode, this wraps a `*mut llama_model`.
pub struct LlamaModel {
    #[cfg(llama_stub)]
    _phantom: (),
    #[cfg(not(llama_stub))]
    inner: real::LlamaModelInner,
}

/// Opaque handle to a llama.cpp context (KV cache + compute state).
pub struct LlamaContext {
    #[cfg(llama_stub)]
    _phantom: (),
    #[cfg(not(llama_stub))]
    inner: real::LlamaContextInner,
}
